def merge_intervals(intervals):
    if not intervals:
        return []
    intervals = sorted(intervals)
    out = [intervals[0][:]]
    for a, b in intervals[1:]:
        if a <= out[-1][1]:
            out[-1][1] = max(out[-1][1], b)
        else:
            out.append([a, b])
    return out
```

